import type { Agreement, DealEvent, PaymentRequest, Receipt, Session } from "../types.js";

/**
 * Storage interface shared by the in-memory store (no SUPABASE_URL) and the Supabase store.
 * IDs are generated by the app, so both implementations behave identically.
 */
export interface Store {
  readonly kind: "memory" | "supabase";

  insertSession(s: Session): Promise<Session>;
  getSession(id: string): Promise<Session | null>;
  getSessionByJoinCode(code: string): Promise<Session | null>;
  listSessions(): Promise<Session[]>;
  updateSession(id: string, patch: Partial<Session>): Promise<Session>;

  insertEvent(e: DealEvent): Promise<DealEvent>;
  listEvents(sessionId: string): Promise<DealEvent[]>; // ordered by seq

  insertAgreement(a: Agreement): Promise<Agreement>;
  getAgreement(id: string): Promise<Agreement | null>;
  getLatestAgreement(sessionId: string): Promise<Agreement | null>;
  updateAgreement(id: string, patch: Partial<Agreement>): Promise<Agreement>;

  insertPaymentRequest(p: PaymentRequest): Promise<PaymentRequest>;
  getPaymentRequest(id: string): Promise<PaymentRequest | null>;
  listPaymentRequests(sessionId: string): Promise<PaymentRequest[]>; // ordered by created_at
  updatePaymentRequest(id: string, patch: Partial<PaymentRequest>): Promise<PaymentRequest>;

  insertReceipt(r: Receipt): Promise<Receipt>;
  getReceiptForSession(sessionId: string): Promise<Receipt | null>;

  deleteAll(): Promise<void>;
}

export class NotFoundError extends Error {
  statusCode = 404;
}

/** Defaults for sessions stored before the auto-session fields existed (set-up sessions: auto false, detected true). */
export function withSessionDefaults(s: Session): Session {
  return {
    ...s,
    listing: s.listing ?? null,
    condition_checks: s.condition_checks ?? [],
    auto: s.auto ?? false,
    detected: s.detected ?? true,
    ended_at: s.ended_at ?? null,
    summary: s.summary ?? null,
  };
}
